<script setup>import {ref} from 'vue';import {albums} from '../data.js';import Gallery from '../components/Gallery.vue';import PhotoViewer from '../components/PhotoViewer.vue';import {readArray} from '../storage.js';const active=ref(null);const ids=ref(readArray('casil-client-favorites'));function favorite(p){ids.value=ids.value.includes(p.id)?ids.value.filter(x=>x!==p.id):[...ids.value,p.id];localStorage.setItem('casil-client-favorites',JSON.stringify(ids.value))}function move(n){const list=albums[0].photos;let i=list.findIndex(p=>p.id===active.value.id);active.value=list[(i+n+list.length)%list.length]}</script><template><section class="page-hero"><span class="eyebrow">DEMO MODE  |  Client gallery</span><h1>Your moments,<br/>together again.</h1><p>Explore sample albums and choose favorites to revisit.</p></section><section class="section"><div class="notice">This is a public frontend demonstration, not a secure private gallery. All bundled photos and data can be inspected by visitors.</div><div v-for="album in albums" :key="album.id" class="album"><div class="section-head"><div><span class="eyebrow">Client album</span><h2>{{album.name}}</h2></div><span class="muted">{{album.photos.length}} photographs</span></div><Gallery :photos="album.photos" :favorites="ids" @favorite="favorite" @open="active=$event"/></div><PhotoViewer :photo="active" @close="active=null" @move="move"/></section></template>
